import { redirect } from "next/navigation"

import { EmptyState } from "@/components/brand"
import {
  CustomerFlowShell,
  CustomerReceipt,
} from "@/components/customer/customer-flow-system"
import {
  getExistingMembershipForCurrentUser,
  resolveQrForJoin,
} from "@/lib/customer/join"
import { RateLimitError } from "@/lib/security/rate-limit"

type PublicQrPageProps = {
  params: Promise<{
    qrId: string
  }>
}

export default async function PublicQrPage({ params }: PublicQrPageProps) {
  const { qrId } = await params
  let qrContext: Awaited<ReturnType<typeof resolveQrForJoin>>

  try {
    qrContext = await resolveQrForJoin(qrId)
  } catch (error) {
    if (error instanceof RateLimitError) {
      return <UnavailableQr />
    }

    return <UnavailableQr />
  }

  if (!qrContext || !qrContext.available) {
    return <UnavailableQr />
  }

  const membership = await getExistingMembershipForCurrentUser(
    qrContext.merchant.id
  )
  const joinUrl = `/m/${qrContext.merchant.business_slug}/join?qr=${qrContext.qrId}`

  if (membership) {
    redirect(`/card/${membership.id}/stamp?qr=${qrContext.qrId}`)
  }

  redirect(joinUrl)
}

function UnavailableQr() {
  return (
    <CustomerFlowShell
      eyebrow="QR"
      title="Card unavailable"
      description="Ask the venue team for the current loyalty QR."
      className="content-center"
      screenLabel="Unavailable QR"
    >
      <CustomerReceipt
        venueName="Nabaperks"
        title="This loyalty card is unavailable"
        eyebrow="QR unavailable"
      >
        <EmptyState
          title="This loyalty card is unavailable"
          description="Ask a team member for the current loyalty QR."
          headingLevel={1}
          className="w-full"
        />
      </CustomerReceipt>
    </CustomerFlowShell>
  )
}

import Link from "next/link"
import { notFound } from "next/navigation"

import {
  CustomerActionNote,
  CustomerFlowShell,
  CustomerStampCard,
} from "@/components/customer/customer-flow-system"
import { StatusBanner } from "@/components/loyalty"
import { Button } from "@/components/ui/button"
import { getMerchantJoinContext } from "@/lib/customer/join"

type MerchantRewardsPageProps = {
  params: Promise<{
    merchantSlug: string
  }>
}

export default async function MerchantRewardsPage({
  params,
}: MerchantRewardsPageProps) {
  const { merchantSlug } = await params
  let context: Awaited<ReturnType<typeof getMerchantJoinContext>>

  try {
    context = await getMerchantJoinContext(merchantSlug)
  } catch {
    return <UnavailableLanding />
  }

  if (!context) {
    notFound()
  }

  if (!context.available) {
    return <UnavailableLanding />
  }

  const { merchant, loyaltyCard } = context

  return (
    <CustomerFlowShell
      eyebrow="No app loyalty"
      title="Your first stamp is waiting."
      description={`${merchant.business_name} keeps this card in your browser. ${loyaltyCard.stamps_required} visits unseal a mystery reward.`}
      className="content-center"
      screenLabel="Merchant loyalty preview"
    >
      <CustomerStampCard
        venueName={merchant.business_name}
        cardName={loyaltyCard.card_name}
        current={0}
        total={loyaltyCard.stamps_required}
        progressLabel="Visits to reward"
        rewardLocked
        rewardTitle="Mystery reward, sealed"
        rewardDescription={`Collect ${loyaltyCard.stamps_required} stamps to break the seal. No app, no plastic.`}
      >
        <CustomerActionNote title="Scan at the counter" tone="accent">
          Add a stamp from the venue QR once per UK business day.
        </CustomerActionNote>
      </CustomerStampCard>

      <div className="grid gap-3">
        <Button asChild size="lg" className="w-full">
          <Link href={`/m/${merchantSlug}/join`}>Keep my card</Link>
        </Button>
        <Button asChild size="lg" variant="secondary" className="w-full">
          <Link href={`/merchant/${merchantSlug}/terms`}>
            View reward terms
          </Link>
        </Button>
      </div>
    </CustomerFlowShell>
  )
}

function UnavailableLanding() {
  return (
    <CustomerFlowShell
      screenLabel="Unavailable loyalty"
      className="content-center"
    >
      <StatusBanner
        title="This loyalty card is unavailable"
        tone="neutral"
        className="text-center"
      >
        Ask a team member for the current loyalty QR.
      </StatusBanner>
    </CustomerFlowShell>
  )
}

import Link from "next/link"

import {
  CustomerIdentityForm,
  CustomerJoinForm,
} from "@/components/customer/join-forms"
import {
  CustomerActionNote,
  CustomerFlowShell,
  CustomerStampCard,
} from "@/components/customer/customer-flow-system"
import { StatusBanner } from "@/components/loyalty"
import { Button } from "@/components/ui/button"
import { getCurrentCustomer } from "@/lib/customer/identity"
import {
  getExistingMembershipForCurrentUser,
  getMerchantJoinContext,
} from "@/lib/customer/join"

type MerchantJoinPageProps = {
  params: Promise<{
    merchantSlug: string
  }>
  searchParams: Promise<{
    qr?: string
    membership?: string
  }>
}

export default async function MerchantJoinPage({
  params,
  searchParams,
}: MerchantJoinPageProps) {
  const { merchantSlug } = await params
  const query = await searchParams
  let context: Awaited<ReturnType<typeof getMerchantJoinContext>>

  try {
    context = await getMerchantJoinContext(merchantSlug, query.qr)
  } catch {
    return <UnavailableJoin />
  }

  if (!context?.available) {
    return <UnavailableJoin />
  }

  const customer = await getCurrentCustomer()
  const membership = customer
    ? await getExistingMembershipForCurrentUser(context.merchant.id)
    : null
  const merchantTermsUrl = `/merchant/${merchantSlug}/terms`

  return (
    <CustomerFlowShell
      eyebrow="Scanned at the counter"
      title="Your first stamp is waiting."
      description={`${context.merchant.business_name} keeps this card in your browser. One text, no password.`}
      className="content-center"
      screenLabel="Customer join"
    >
      <CustomerStampCard
        venueName={context.merchant.business_name}
        cardName={context.loyaltyCard.card_name}
        current={membership?.current_stamp_count ?? 0}
        total={context.loyaltyCard.stamps_required}
        progressLabel="Visits to reveal"
        rewardLocked
        rewardTitle="Mystery reward, sealed"
        rewardDescription={
          <>
            Your assigned reward stays hidden until the final stamp and can be
            redeemed from the next UK business day.
            {context.loyaltyCard.min_spend_pence !== null ? (
              <>
                {" "}
                Minimum spend {formatPence(context.loyaltyCard.min_spend_pence)}
                .
              </>
            ) : null}
          </>
        }
      >
        <CustomerActionNote title="No app to download" tone="accent">
          Save the card to your phone number, then scan the venue QR when you
          visit.
        </CustomerActionNote>
        <Link
          className="inline-flex w-fit text-xs font-bold underline underline-offset-4"
          href={merchantTermsUrl}
        >
          View full venue terms
        </Link>
      </CustomerStampCard>

      {membership ? (
        <CustomerCardSummary
          membershipId={membership.id}
          stampsRequired={context.loyaltyCard.stamps_required}
          currentStampCount={membership.current_stamp_count}
          qrId={query.qr}
        />
      ) : customer ? (
        <CustomerJoinForm
          merchantSlug={merchantSlug}
          qrId={query.qr}
          merchantTermsUrl={merchantTermsUrl}
        />
      ) : (
        <CustomerIdentityForm merchantSlug={merchantSlug} qrId={query.qr} />
      )}
    </CustomerFlowShell>
  )
}

function CustomerCardSummary({
  membershipId,
  stampsRequired,
  currentStampCount,
  qrId,
}: {
  membershipId: string
  stampsRequired: number
  currentStampCount: number
  qrId?: string
}) {
  return (
    <div className="grid gap-4">
      <StatusBanner title="You're already joined" tone="success">
        Your stamp card is ready. Continue from your current progress.
      </StatusBanner>
      <CustomerActionNote title="Current progress" tone="leaf">
        {currentStampCount} of {stampsRequired} stamps collected.
      </CustomerActionNote>
      <Button asChild size="lg" className="w-full">
        <Link
          href={
            qrId
              ? `/card/${membershipId}/stamp?qr=${qrId}`
              : `/card/${membershipId}`
          }
        >
          Open your stamp card
        </Link>
      </Button>
    </div>
  )
}

function UnavailableJoin() {
  return (
    <CustomerFlowShell
      screenLabel="Unavailable loyalty"
      className="content-center"
    >
      <StatusBanner
        title="This loyalty card is unavailable"
        tone="neutral"
        className="text-center"
      >
        Ask a team member for the current loyalty QR.
      </StatusBanner>
    </CustomerFlowShell>
  )
}

function formatPence(pence: number) {
  return new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "GBP",
  }).format(pence / 100)
}

import type { ReactNode } from "react"
import Link from "next/link"

import {
  CustomerFlowShell,
  CustomerStampCard,
} from "@/components/customer/customer-flow-system"
import { StatusBanner } from "@/components/loyalty"
import { StampCelebration } from "@/components/motion"
import { Button } from "@/components/ui/button"
import { getCustomerCardState } from "@/lib/customer/card"

type CustomerCardPageProps = {
  params: Promise<{
    membershipId: string
  }>
  searchParams: Promise<{
    stamp?: string
    reward?: string
    geo?: string
  }>
}

export default async function CustomerCardPage({
  params,
  searchParams,
}: CustomerCardPageProps) {
  const { membershipId } = await params
  const { stamp, reward, geo } = await searchParams
  const cardState = await getCustomerCardState(membershipId)

  if (cardState.status !== "ready") {
    return <CardAccessState status={cardState.status} />
  }

  if (!cardState.loyaltyCard) {
    return (
      <CardShell>
        <UnavailableCard message="This loyalty card is unavailable." />
      </CardShell>
    )
  }

  const { membership, merchant, loyaltyCard, latestReward } = cardState
  const target = loyaltyCard.stamps_required
  const current = Math.min(membership.current_stamp_count, target)
  const rewardUnlocked = latestReward?.status === "unlocked"
  const rewardRedeemable =
    rewardUnlocked &&
    (!latestReward.redeemable_from ||
      latestReward.redeemable_from <= ukTodayIso())
  const stampsBlocked = cardState.billingStatus === "cancelled"
  const rewardTitle = rewardUnlocked
    ? latestReward.reward_name
    : "Something's under there."
  const rewardDescription = rewardUnlocked ? (
    <>
      {latestReward.reward_terms}
      {latestReward.min_spend_pence !== null ? (
        <> Minimum spend {formatPence(latestReward.min_spend_pence)}.</>
      ) : null}
      {rewardRedeemable
        ? " Reward ready to redeem."
        : " Give it a day to breathe - it's yours from opening time tomorrow."}
    </>
  ) : (
    <>
      Mystery reward stays sealed until the final stamp.{" "}
      {loyaltyCard.reward_terms}
    </>
  )

  return (
    <CardShell
      title="Your card"
      description={`${merchant.business_name} - ${loyaltyCard.card_name}`}
    >
      <div className="grid gap-4">
        <Link
          href="/wallet"
          className="inline-flex w-fit items-center gap-1 text-sm font-bold text-ink-soft underline-offset-4 transition-colors hover:text-foreground hover:underline"
        >
          <span aria-hidden="true">←</span> Your cards
        </Link>
        {stamp === "issued" ? (
          <StampCelebration>
            <StatusBanner
              title="Stamp added."
              tone="success"
              className="text-center"
            >
              That&apos;s one. Your progress has been updated.
              {geo === "flagged"
                ? " Location could not be confirmed, so the venue may review it."
                : null}
            </StatusBanner>
          </StampCelebration>
        ) : null}
        {reward === "redeemed" ? (
          <StatusBanner
            title="Reward redeemed."
            tone="success"
            className="text-center"
          >
            New stamp cycle started.
          </StatusBanner>
        ) : null}

        <CustomerStampCard
          venueName={merchant.business_name}
          cardName={loyaltyCard.card_name}
          current={current}
          total={target}
          slamIndex={stamp === "issued" ? current - 1 : -1}
          rewardLocked={!rewardUnlocked}
          rewardTitle={rewardTitle}
          rewardDescription={rewardDescription}
        >
          {cardState.unavailableReason ? (
            <UnavailableCard message={cardState.unavailableReason} />
          ) : rewardUnlocked && rewardRedeemable ? (
            <Button asChild size="lg" variant="reward" className="w-full">
              <Link href={`/reward/${latestReward.id}`}>Redeem reward</Link>
            </Button>
          ) : rewardUnlocked ? (
            <StatusNotice
              title="Give it a day to breathe"
              message="It's yours from opening time tomorrow."
            />
          ) : stampsBlocked ? (
            <StatusNotice message="This merchant is not accepting new stamps right now." />
          ) : (
            <StatusBanner
              title="Scan the venue code to add your stamp."
              tone="neutral"
            >
              Use the printed QR in the venue. One stamp is available per UK
              business day.
            </StatusBanner>
          )}
        </CustomerStampCard>
      </div>
    </CardShell>
  )
}

function UnavailableCard({ message }: { message: string }) {
  return (
    <StatusBanner title="Card unavailable" tone="error">
      {message}
    </StatusBanner>
  )
}

function StatusNotice({
  title = "Stamps unavailable",
  message,
}: {
  title?: string
  message: string
}) {
  return (
    <StatusBanner title={title} tone="warning">
      {message}
    </StatusBanner>
  )
}

function CardAccessState({
  status,
}: {
  status: "unauthenticated" | "unauthorized" | "not_found"
}) {
  const message =
    status === "unauthenticated"
      ? "Verify your identity from the venue QR to view this card."
      : status === "unauthorized"
        ? "This card belongs to another customer."
        : "This card could not be found."

  return (
    <CardShell>
      <section className="surface-card p-6 text-center">
        <p className="font-mono text-xs text-muted-foreground uppercase">
          Nabaperks loyalty
        </p>
        <h1 className="mt-2 text-3xl leading-tight font-extrabold">
          Card unavailable
        </h1>
        <p className="mt-3 text-sm leading-6 text-muted-foreground">
          {message}
        </p>
      </section>
    </CardShell>
  )
}

function CardShell({
  children,
  title = "Card unavailable",
  description,
}: {
  children: ReactNode
  title?: ReactNode
  description?: ReactNode
}) {
  return (
    <CustomerFlowShell
      eyebrow="Nabaperks loyalty"
      title={title}
      description={description}
      screenLabel="Customer card"
    >
      {children}
    </CustomerFlowShell>
  )
}

function formatPence(pence: number) {
  return new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "GBP",
  }).format(pence / 100)
}

function ukTodayIso() {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/London",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date())
  const year = parts.find((part) => part.type === "year")?.value
  const month = parts.find((part) => part.type === "month")?.value
  const day = parts.find((part) => part.type === "day")?.value

  return `${year}-${month}-${day}`
}

import type { ReactNode } from "react"
import Link from "next/link"
import { redirect } from "next/navigation"

import {
  CustomerActionNote,
  CustomerFlowShell,
  CustomerReceipt,
} from "@/components/customer/customer-flow-system"
import { SelfServiceStampForm } from "@/components/customer/self-service-forms"
import { StatusBanner } from "@/components/loyalty"
import { Button } from "@/components/ui/button"
import { getCustomerCardState } from "@/lib/customer/card"
import { getStampQrContextForMembership } from "@/lib/customer/join"
import { getMembershipLocationRequirement } from "@/lib/customer/stamp"
import { isRedeemableFrom } from "@/lib/customer/uk-date"

export const dynamic = "force-dynamic"

type StampPageProps = {
  params: Promise<{
    membershipId: string
  }>
  searchParams: Promise<{
    qr?: string
  }>
}

export default async function StampPage({
  params,
  searchParams,
}: StampPageProps) {
  const { membershipId } = await params
  const { qr } = await searchParams
  const cardState = await getCustomerCardState(membershipId)

  if (cardState.status !== "ready") {
    return (
      <StampShell membershipId={membershipId} showBack={false}>
        <StatusBanner title="Card unavailable" tone="error">
          {cardState.status === "unauthenticated"
            ? "Verify your identity from the venue QR to add a stamp."
            : cardState.status === "unauthorized"
              ? "This card belongs to another customer."
              : "This card could not be found."}
        </StatusBanner>
      </StampShell>
    )
  }

  if (cardState.unavailableReason) {
    return (
      <StampShell membershipId={membershipId}>
        <StatusBanner title="Stamps unavailable" tone="warning">
          {cardState.unavailableReason}
        </StatusBanner>
      </StampShell>
    )
  }

  // An unlocked reward blocks new stamps until it is redeemed. Route the customer
  // to redeem now if it is redeemable, or show a calm wait notice if redemption
  // opens on the next UK business day — instead of letting a tap hit a confusing
  // "redeem it first" error from the stamp RPC.
  const unlockedReward =
    cardState.latestReward?.status === "unlocked"
      ? cardState.latestReward
      : null

  if (unlockedReward) {
    if (isRedeemableFrom(unlockedReward.redeemable_from)) {
      redirect(`/reward/${unlockedReward.id}`)
    }

    return (
      <StampShell
        membershipId={membershipId}
        venueName={cardState.merchant.business_name}
      >
        <StatusBanner title="Reward ready" tone="success">
          Your reward has unlocked. Redeem it from the next UK business day — no
          more stamps until you do.
        </StatusBanner>
      </StampShell>
    )
  }

  if (!qr) {
    return (
      <StampShell membershipId={membershipId}>
        <StatusBanner
          title="Scan the venue code to add your stamp."
          tone="neutral"
        >
          Open this screen from the printed venue QR so the stamp is tied to the
          right business.
        </StatusBanner>
      </StampShell>
    )
  }

  const qrContext = await getStampQrContextForMembership(membershipId, qr)

  if (!qrContext) {
    return (
      <StampShell membershipId={membershipId}>
        <StatusBanner title="QR unavailable" tone="warning">
          Scan the venue code again to add your stamp.
        </StatusBanner>
      </StampShell>
    )
  }

  const locationRequirement =
    await getMembershipLocationRequirement(membershipId)

  return (
    <StampShell
      membershipId={membershipId}
      venueName={cardState.merchant.business_name}
    >
      <CustomerReceipt
        venueName={cardState.merchant.business_name}
        title="Stamp it here"
        eyebrow="Today's visit"
      >
        <StatusBanner title="Ready to add today's stamp." tone="success">
          Tap once while you are at the venue. Stamps are limited to one per UK
          business day.
        </StatusBanner>
        <CustomerActionNote
          title="The printed QR ties this to the venue"
          tone="leaf"
        >
          Location can be checked when available, but the action still continues
          if your browser cannot share it.
        </CustomerActionNote>
        <SelfServiceStampForm
          membershipId={membershipId}
          qrId={qrContext.qrId ?? qr}
          requireGeofence={locationRequirement.requireGeofence}
          geofenceRadiusMeters={locationRequirement.geofenceRadiusMeters}
        />
      </CustomerReceipt>
    </StampShell>
  )
}

function StampShell({
  children,
  membershipId,
  venueName,
  showBack = true,
}: {
  children: ReactNode
  membershipId: string
  venueName?: string
  showBack?: boolean
}) {
  return (
    <CustomerFlowShell
      eyebrow="Today's stamp"
      title="Stamp it here"
      description={venueName ?? "Open this from the printed venue QR."}
      screenLabel="Customer stamp"
    >
      <section className="grid gap-5">
        {children}
        {showBack ? (
          <Button asChild size="lg" variant="secondary" className="w-full">
            <Link href={`/card/${membershipId}`}>Back to card</Link>
          </Button>
        ) : null}
      </section>
    </CustomerFlowShell>
  )
}

"use client"

import { CustomerShell } from "@/components/layout"
import { StatusBanner } from "@/components/loyalty"

export default function CustomerCardError() {
  return (
    <CustomerShell className="grid content-center">
      <StatusBanner title="Card unavailable" tone="error" className="text-center">
        This card could not be loaded safely. Ask a team member for the current
        loyalty QR and try again.
      </StatusBanner>
    </CustomerShell>
  )
}

import type { ReactNode } from "react"
import Link from "next/link"

import {
  CustomerActionNote,
  CustomerFlowShell,
  CustomerReceipt,
  CustomerRewardSeal,
} from "@/components/customer/customer-flow-system"
import { SelfServiceRedeemForm } from "@/components/customer/self-service-forms"
import { RewardTeaser, StatusBanner } from "@/components/loyalty"
import { Button } from "@/components/ui/button"
import { getCustomerRewardState } from "@/lib/customer/reward"
import { getRewardLocationRequirement } from "@/lib/customer/stamp"

export const dynamic = "force-dynamic"

type RewardPageProps = {
  params: Promise<{
    rewardId: string
  }>
}

export default async function RewardPage({ params }: RewardPageProps) {
  const { rewardId } = await params
  const rewardState = await getCustomerRewardState(rewardId)

  if (rewardState.status !== "ready") {
    return <RewardAccessState status={rewardState.status} />
  }

  const { reward, assignedReward, loyaltyCard, merchant, membership } =
    rewardState
  const locationRequirement = await getRewardLocationRequirement(reward.id)
  const redeemable =
    reward.status === "unlocked" &&
    !rewardState.unavailableReason &&
    membership.current_stamp_count >= loyaltyCard.stamps_required &&
    (!reward.redeemable_from || reward.redeemable_from <= ukTodayIso())

  return (
    <RewardShell
      title={assignedReward.reward_name}
      description={`${merchant.business_name} - show this at the counter when ready.`}
    >
      <CustomerReceipt
        venueName={merchant.business_name}
        title={assignedReward.reward_name}
        eyebrow="Mystery reward"
        footerLeft={`CARD Nº ${reward.membership_id.slice(0, 8).toUpperCase()}`}
      >
        <CustomerRewardSeal
          revealed={redeemable}
          caption={redeemable ? "Ready to redeem" : "Reward sealed"}
        />
        <RewardTeaser
          locked={false}
          title={assignedReward.reward_name}
          description={
            <>
              {assignedReward.reward_terms}
              {assignedReward.min_spend_pence !== null ? (
                <>
                  {" "}
                  Minimum spend {formatPence(assignedReward.min_spend_pence)}.
                </>
              ) : null}
            </>
          }
        />
        <CustomerActionNote
          title="Counter check"
          tone={redeemable ? "leaf" : "sun"}
        >
          Rewards become redeemable from the next UK business day after the
          final stamp.
        </CustomerActionNote>

        <RewardStatusPanel
          status={reward.status}
          unavailableReason={rewardState.unavailableReason}
          redeemable={redeemable}
          redeemableFrom={reward.redeemable_from}
        />

        {redeemable ? (
          <SelfServiceRedeemForm
            rewardId={reward.id}
            requireGeofence={locationRequirement.requireGeofence}
            geofenceRadiusMeters={locationRequirement.geofenceRadiusMeters}
          />
        ) : (
          <Button asChild size="lg" variant="secondary" className="w-full">
            <Link href={`/card/${reward.membership_id}`}>Return to card</Link>
          </Button>
        )}
      </CustomerReceipt>
    </RewardShell>
  )
}

function RewardStatusPanel({
  status,
  unavailableReason,
  redeemable,
  redeemableFrom,
}: {
  status: string
  unavailableReason?: string
  redeemable: boolean
  redeemableFrom: string | null
}) {
  if (unavailableReason) {
    return (
      <StatusBanner title="Reward unavailable" tone="error">
        {unavailableReason}
      </StatusBanner>
    )
  }

  if (status === "redeemed") {
    return (
      <StatusBanner title="Reward redeemed" tone="neutral">
        This reward has already been redeemed.
      </StatusBanner>
    )
  }

  if (status === "cancelled" || status === "expired") {
    return (
      <StatusBanner title="Reward unavailable" tone="error">
        This reward is no longer available.
      </StatusBanner>
    )
  }

  if (
    status === "unlocked" &&
    redeemableFrom &&
    redeemableFrom > ukTodayIso()
  ) {
    return (
      <StatusBanner title="Give it a day to breathe" tone="warning">
        It&apos;s yours from opening time tomorrow.
      </StatusBanner>
    )
  }

  if (!redeemable) {
    return (
      <StatusBanner title="Not ready yet" tone="neutral">
        This reward is not ready to redeem.
      </StatusBanner>
    )
  }

  return (
    <StatusBanner title="Ready to redeem." tone="success">
      Tap redeem while you are at the venue, then show the redeemed card if
      asked.
    </StatusBanner>
  )
}

function RewardAccessState({
  status,
}: {
  status: "unauthenticated" | "unauthorized" | "not_found"
}) {
  const message =
    status === "unauthenticated"
      ? "Verify your identity from the venue QR to view this reward."
      : status === "unauthorized"
        ? "This reward belongs to another customer."
        : "This reward could not be found."

  return (
    <RewardShell>
      <CustomerReceipt
        venueName="Nabaperks"
        title="Reward unavailable"
        eyebrow="Nabaperks loyalty"
      >
        <p className="font-mono text-xs text-muted-foreground uppercase">
          Nabaperks loyalty
        </p>
        <p className="mt-3 text-sm leading-6 text-muted-foreground">
          {message}
        </p>
      </CustomerReceipt>
    </RewardShell>
  )
}

function RewardShell({
  children,
  title = "Reward",
  description,
}: {
  children: ReactNode
  title?: ReactNode
  description?: ReactNode
}) {
  return (
    <CustomerFlowShell
      eyebrow="Reward"
      title={title}
      description={description}
      screenLabel="Customer reward"
    >
      {children}
    </CustomerFlowShell>
  )
}

function formatPence(pence: number) {
  return new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "GBP",
  }).format(pence / 100)
}

function ukTodayIso() {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/London",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date())
  const year = parts.find((part) => part.type === "year")?.value
  const month = parts.find((part) => part.type === "month")?.value
  const day = parts.find((part) => part.type === "day")?.value

  return `${year}-${month}-${day}`
}

