:root {
  /* Wet Ink base palette — warm paper, warm near-black ink, flat spot inks. */
  --w-paper: #f6f1e6;
  --w-paper-2: #ece5d4;
  --w-card: #fbf8f1;
  --w-ink: #211c16;
  --w-ink-soft: #6b6257;
