  --w-accent: #e8430f;
  --w-accent-ink: #ffffff;
  --w-cobalt: #2b43c8;
  --w-leaf: #1e8a4c;
  --w-sun: #f5a623;

  --w-shadow-color: var(--w-ink);

  --paper-cream: var(--w-card);
  --espresso-ink: var(--w-ink);
  --soft-mint: color-mix(in srgb, var(--w-leaf) 10%, var(--w-paper));
