  --surface-dim: #e0d7c2;
  --surface-container: var(--w-paper-2);
  --surface-container-high: #e6ddc9;

  --background: var(--w-paper);
  --foreground: var(--w-ink);

  --card: var(--w-card);
  --card-foreground: var(--w-ink);

  --popover: var(--w-card);
  --popover-foreground: var(--w-ink);

  --primary: var(--w-accent);
  --primary-foreground: var(--w-accent-ink);

  --secondary: var(--w-paper-2);
  --secondary-foreground: var(--w-ink);

  --muted: var(--w-paper-2);
  --muted-foreground: var(--w-ink-soft);

  --accent: var(--w-paper-2);
  --accent-foreground: var(--w-ink);

  --destructive: #c0301c;
  --destructive-foreground: #ffffff;

  --border: var(--w-line);
  --input: var(--w-line);
  --ring: var(--w-accent);

  /* Loyalty semantics */
  --stamp: var(--w-accent);
  --stamp-foreground: var(--w-accent-ink);
  --stamp-empty: var(--w-line);

  --seal: var(--w-sun);
