    gap: 6px;
    font-family:
      var(--font-space-mono), ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border: 1.5px solid var(--w-line);
    border-radius: 999px;
    padding: 4px 11px;
    white-space: nowrap;
    color: var(--w-ink-soft);
  }

  /* Dashed receipt rule between sections. */
  .w-rule {
    border: none;
    border-top: 2px dashed var(--w-line);
    margin: 14px 0;
  }

  /* Perforated zigzag bottom edge for receipt surfaces. */
  .receipt-edge {
    height: 12px;
    margin-top: -1px;
    background:
      linear-gradient(
          -45deg,
          transparent 8.5px,
          var(--w-ink) 8.5px,
          var(--w-ink) 11px,
          var(--w-card) 11px
        )
        0 0 / 17px 100%,
      linear-gradient(
          45deg,
          transparent 8.5px,
          var(--w-ink) 8.5px,
          var(--w-ink) 11px,
          var(--w-card) 11px
        )
        0 0 / 17px 100%;
  }
}

/* ============================================================
   Wet Ink layer — v2 treatments applied over the shadcn
   primitives through their data-slot hooks. The component
   files and their APIs stay untouched; this layer only
   restyles shape, border, weight, and elevation.
   ============================================================ */

[data-slot="button"]:not([data-variant="ghost"]):not([data-variant="link"]) {
  border: 2px solid var(--w-ink);
  border-radius: var(--radius-lg);
  font-weight: 700;
  letter-spacing: 0.01em;
  --tw-shadow: 3px 3px 0 var(--w-shadow-color);
}

[data-slot="button"]:not([data-variant="ghost"]):not(
    [data-variant="link"]
  ):active:not(:disabled, [aria-disabled="true"]) {
  translate: 2px 2px;
  scale: none;
  transform: none;
  --tw-shadow: 1px 1px 0 var(--w-shadow-color);
}

[data-slot="button"][data-variant="ghost"],
[data-slot="button"][data-variant="link"] {
  border-radius: var(--radius-lg);
}

[data-slot="card"] {
  border: 2px solid var(--w-ink);
  border-radius: var(--radius-lg);
  --tw-shadow: 4px 4px 0 var(--w-shadow-color);
}

[data-slot="card-title"] {
  font-weight: 800;
}

[data-slot="input"],
[data-slot="textarea"] {
  border-width: 2px;
  border-color: var(--w-ink);
  border-radius: var(--radius-lg);
  background: var(--card);
}

[data-slot="input-otp-slot"] {
  border-color: var(--w-ink);
  border-top-width: 2px;
  border-bottom-width: 2px;
  border-right-width: 2px;
  background: var(--card);
}

[data-slot="input-otp-slot"]:first-child {
  border-left-width: 2px;
}

[data-slot="alert"] {
  border-radius: var(--radius-lg);
}

[data-slot="tabs-list"],
[data-slot="tabs-trigger"] {
  border-radius: var(--radius-lg);
}

[data-slot="empty"] {
  border-radius: var(--radius-lg);
}

[data-slot="badge"] {
  border-radius: 999px;
  font-family:
    var(--font-space-mono), ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

[data-slot="sheet-content"] {
  background: var(--card);
}

[data-slot="sheet-content"][data-side="bottom"] {
  border-radius: var(--radius-sheet) var(--radius-sheet) 0 0;
  border-top: 2px solid var(--w-ink);
}

[data-slot="sheet-content"][data-side="top"] {
  border-radius: 0 0 var(--radius-sheet) var(--radius-sheet);
  border-bottom: 2px solid var(--w-ink);
}

[data-slot="sheet-content"][data-side="left"] {
  border-right: 2px solid var(--w-ink);
}

[data-slot="sheet-content"][data-side="right"] {
  border-left: 2px solid var(--w-ink);
}

[data-slot="sheet-overlay"] {
  background: rgba(33, 28, 22, 0.5);
}

/* ---------- the motion vocabulary ---------- */

@keyframes w-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes w-slam {
  0% {
    opacity: 0;
    transform: scale(2.6) rotate(-14deg);
  }
  62% {
    opacity: 1;
    transform: scale(0.94) rotate(-5deg);
  }
  80% {
    transform: scale(1.04) rotate(-7deg);
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(-6deg);
  }
}
@keyframes w-soft-stamp {
  0% {
    opacity: 0;
    transform: scale(1.18) rotate(-6deg);
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(-6deg);
  }
}
@keyframes w-shake {
  0%,
  100% {
    transform: translate(0, 0) rotate(0deg);
  }
  20% {
    transform: translate(-3px, 2px) rotate(-0.5deg);
  }
  45% {
    transform: translate(3px, -2px) rotate(0.5deg);
  }
  70% {
    transform: translate(-2px, 1px) rotate(-0.25deg);
  }
}
@keyframes w-ripple {
  0% {
    opacity: 0.9;
    transform: scale(0.4);
  }
  100% {
    opacity: 0;
    transform: scale(2.1);
  }
}
@keyframes w-wiggle {
  0%,
  100% {
    transform: rotate(-3deg) scale(1);
  }
  50% {
    transform: rotate(3deg) scale(1.03);
  }
}
@keyframes w-pop {
  0% {
    opacity: 0;
    transform: scale(0.6);
  }
  70% {
    transform: scale(1.08);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes w-sheet-up {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}
@keyframes w-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }

  .pressable:active:not(:disabled, [aria-disabled="true"]) {
    transform: translateY(1px);
  }

  [data-slot="button"]:not([data-variant="ghost"]):not(
      [data-variant="link"]
    ):active:not(:disabled, [aria-disabled="true"]) {
    translate: 1px 1px;
  }
}
